from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List, Tuple


def nontrivial_cuts(n: int) -> List[FrozenSet[int]]:
    """All nonempty proper subsets of {0,...,n-1}: the nontrivial bipartitions."""
    cuts: List[FrozenSet[int]] = []
    for size in range(1, n):
        for combo in combinations(range(n), size):
            cuts.append(frozenset(combo))
    return cuts


def phi_multicut(rank: Callable[[FrozenSet[int]], int], n: int) -> int:
    """Phi = min over nontrivial cuts of (rank(A) - 1) -- the IIT min-information value."""
    if n < 2:
        raise ValueError("need n >= 2")
    return min(rank(A) - 1 for A in nontrivial_cuts(n))


def minimum_information_partition(
    rank: Callable[[FrozenSet[int]], int], n: int
) -> Tuple[FrozenSet[int], int]:
    """Return a cut realizing Phi (the Minimum Information Partition) and its value."""
    best = min(nontrivial_cuts(n), key=lambda A: rank(A) - 1)
    return best, rank(best) - 1


if __name__ == "__main__":
    n, D = 4, 3
    print("Maximally entangled (rank D everywhere): Phi =",
          phi_multicut(lambda A: D, n), "expected", D - 1)
    mip, val = minimum_information_partition(lambda A: 1 if A == frozenset({0}) else D, n)
    print("Product cut present -> MIP =", set(mip), "Phi =", val, "(reducible)")

from __future__ import annotations
from typing import Callable, Dict, List, Sequence


def dist_to_set(d: Callable[[int, int], float], S: Sequence[int], v: int) -> float:
    """Min-plus distance from v to the set S: min over b in S of d(v, b)."""
    return min(d(v, b) for b in S)


def entanglement_wedge(
    bulk: Sequence[int], boundary: Sequence[int], B: Sequence[int],
    d: Callable[[int, int], float],
) -> List[int]:
    """Bulk vertices strictly closer to B than to boundary \\ B."""
    Bset = set(B)
    Bc = [b for b in boundary if b not in Bset]
    if not Bset or not Bc:
        return list(bulk)
    return [v for v in bulk if dist_to_set(d, list(Bset), v) < dist_to_set(d, Bc, v)]


def boundary_obs(
    bulk: Sequence[int], d: Callable[[int, int], float],
    phi: Callable[[int], float], b: int,
) -> float:
    """Min-plus convolution Obs(phi)(b) = min over v of (phi(v) + d(v, b))."""
    return min(phi(v) + d(v, b) for v in bulk)


if __name__ == "__main__":
    coord: Dict[int, float] = {0: 1.0, 1: 3.0, 2: 6.0, 3: 8.0,
                               10: 0.0, 11: 4.0, 12: 5.0, 13: 9.0}
    d = lambda u, v: abs(coord[u] - coord[v])
    bulk, boundary, B = [0, 1, 2, 3], [10, 11, 12, 13], [10, 11]
    print("Wedge of B:", entanglement_wedge(bulk, boundary, B, d))

from __future__ import annotations
from math import exp, isclose, log
from typing import Sequence


def mincut_entropy(area: Sequence[float], slope: Sequence[float], t: float) -> float:
    """Tropical min-cut entropy S(t) = min_i (a_i + c_i t) -- a (min,+) polynomial."""
    return min(a + c * t for a, c in zip(area, slope))


def critical_bond_dimension(a0: float, a1: float, c0: float, c1: float) -> float:
    """Sharp crossover bond dimension D_c = exp((a0 - a1)/(c1 - c0)) for two cuts."""
    if isclose(c0, c1):
        raise ValueError("equal slopes: no isolated crossover")
    return exp((a0 - a1) / (c1 - c0))


def curvature_proxy(area: Sequence[float], slope: Sequence[float], t: float) -> float:
    """Discrete curvature S(t-1) - 2 S(t) + S(t+1); <= 0 by concavity."""
    return (mincut_entropy(area, slope, t - 1)
            - 2 * mincut_entropy(area, slope, t)
            + mincut_entropy(area, slope, t + 1))


if __name__ == "__main__":
    a, c = [4.0, 0.0], [1.0, 3.0]
    Dc = critical_bond_dimension(a[0], a[1], c[0], c[1])
    print("D_c =", round(Dc, 4), " log D_c =", round(log(Dc), 4))
    for t in [1.0, 2.0, 3.0]:
        print(f"t={t}: S={mincut_entropy(a, c, t):.2f} kappa={curvature_proxy(a, c, t):+.3f}")

