function IntegratedInformation(rank, n):
    require n >= 2
    best <- +infinity ; mip <- none
    for each nonempty proper subset A of {0,...,n-1}:
        require rank(A) >= 1            # nonzero pure state
        v <- rank(A) - 1
        if v < best: best <- v ; mip <- A
    return (best, mip)
